with sources as (select d.stable_key,r.schema_json from clinical_form_definitions d join clinical_form_revisions r on r.definition_id=d.definition_id and r.revision=d.effective_revision where d.stable_key in ('legacy.rosgeneral','legacy.roseyes','legacy.rosearnoseandthroat','legacy.rosbreastpulmonary','legacy.roscardiovascular','legacy.rosgastrointestinal','legacy.rosurinary','legacy.rosreproductive','legacy.rosmusculoskeletal','legacy.rosneurologic','legacy.rosskin','legacy.rospsychiatric','legacy.rosendocrinehematologicallergy')), source_fields as (select case stable_key when 'legacy.rosgeneral' then 10 when 'legacy.roseyes' then 20 when 'legacy.rosearnoseandthroat' then 30 when 'legacy.rosbreastpulmonary' then 40 when 'legacy.roscardiovascular' then 50 when 'legacy.rosgastrointestinal' then 60 when 'legacy.rosurinary' then 70 when 'legacy.rosreproductive' then 80 when 'legacy.rosmusculoskeletal' then 90 when 'legacy.rosneurologic' then 100 when 'legacy.rosskin' then 110 when 'legacy.rospsychiatric' then 120 when 'legacy.rosendocrinehematologicallergy' then 130 end as source_order,field,ordinal from sources cross join lateral jsonb_array_elements(schema_json->'fields') with ordinality as fields(field,ordinal)), schema as (select jsonb_build_object('stableKey','legacy.ros','name','Review of Systems','purpose','Unified legacy form_ros encounter compatibility capture.','contextScope','encounter','owningService','clinical_operations','capability','encounters.auth_a','signaturePolicy','author-only','sections',jsonb_build_array(jsonb_build_object('key','general','title','General','sequence',10,'description','Legacy form_ros general fields.'),jsonb_build_object('key','eyes','title','Eyes','sequence',20,'description','Legacy form_ros eye fields.'),jsonb_build_object('key','ear_nose_throat','title','Ear, Nose and Throat','sequence',30,'description','Legacy form_ros ear, nose, and throat fields.'),jsonb_build_object('key','breast_pulmonary','title','Breast and Pulmonary','sequence',40,'description','Legacy form_ros breast and pulmonary fields.'),jsonb_build_object('key','cardiovascular','title','Cardiovascular','sequence',50,'description','Legacy form_ros cardiovascular fields.'),jsonb_build_object('key','gastrointestinal','title','Gastrointestinal','sequence',60,'description','Legacy form_ros gastrointestinal fields.'),jsonb_build_object('key','urinary','title','Urinary','sequence',70,'description','Legacy form_ros urinary fields.'),jsonb_build_object('key','reproductive','title','Reproductive','sequence',80,'description','Legacy form_ros reproductive fields.'),jsonb_build_object('key','musculoskeletal','title','Musculoskeletal','sequence',90,'description','Legacy form_ros musculoskeletal fields.'),jsonb_build_object('key','neurologic','title','Neurologic','sequence',100,'description','Legacy form_ros neurologic fields.'),jsonb_build_object('key','skin','title','Skin','sequence',110,'description','Legacy form_ros skin fields.'),jsonb_build_object('key','psychiatric','title','Psychiatric','sequence',120,'description','Legacy form_ros psychiatric fields.'),jsonb_build_object('key','endocrine_hematologic_allergy','title','Endocrine, Hematologic and Allergy','sequence',130,'description','Legacy form_ros final fields.')),'fields',(select jsonb_agg(field order by source_order,ordinal) from source_fields),'rules','[]'::jsonb) schema_json)
update clinical_form_definitions set effective_revision=1,updated_at=now(),updated_by='legacy-adoption-seed' where stable_key='legacy.ros' and effective_revision is null;
